use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().and_then(|a| a.get(0).and_then(|v| v.as_array()));
    let [year, month, day] = match arr {
        Some(arr) if arr.len() == 3 => [
            arr[0].as_i64().unwrap_or(0),
            arr[1].as_i64().unwrap_or(0),
            arr[2].as_i64().unwrap_or(0),
        ],
        _ => return Value::Bool(false),
    };

    if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 {
        return Value::Bool(false);
    }

    let is_leap_year = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    let days_in_month = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap_year { 29 } else { 28 },
        _ => return Value::Bool(false),
    };

    if day > days_in_month {
        return Value::Bool(false);
    }

    Value::Bool(true)
}
